# part 2: W7 .. W12.   `E(old, new)` = replace one exact substring; `L(prefix, new)` = replace the whole (single) line that starts with `prefix`.
EDITS = []


def E(old, new, count=1):
    EDITS.append(("sub", old, new, count))


def L(prefix, new):
    EDITS.append(("line", prefix, new, 1))


